CREATE TABLE space_history_document (id INTEGER PRIMARY KEY, active_alternative_id TEXT);
CREATE TABLE space_history_checkpoint (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES space_history_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), checkpoint_id TEXT NOT NULL, parent_checkpoint_id TEXT, message TEXT NOT NULL);
CREATE TABLE space_history_timestamp (id INTEGER PRIMARY KEY REFERENCES space_history_checkpoint(id), actor_high INTEGER NOT NULL CHECK(actor_high BETWEEN 0 AND 4294967295), actor_low INTEGER NOT NULL CHECK(actor_low BETWEEN 0 AND 4294967295), physical_ms_high INTEGER NOT NULL CHECK(physical_ms_high BETWEEN 0 AND 4294967295), physical_ms_low INTEGER NOT NULL CHECK(physical_ms_low BETWEEN 0 AND 4294967295), logical_high INTEGER NOT NULL CHECK(logical_high BETWEEN 0 AND 4294967295), logical_low INTEGER NOT NULL CHECK(logical_low BETWEEN 0 AND 4294967295));
CREATE TABLE space_history_author (id INTEGER PRIMARY KEY, checkpoint_row_id INTEGER NOT NULL REFERENCES space_history_checkpoint(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), author_id TEXT NOT NULL, name TEXT NOT NULL, avatar TEXT);
CREATE TABLE space_history_member_pin (id INTEGER PRIMARY KEY, checkpoint_row_id INTEGER NOT NULL REFERENCES space_history_checkpoint(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), addressed_document_id TEXT NOT NULL, checkpoint_id TEXT NOT NULL, alternative_id TEXT NOT NULL);
CREATE TABLE space_history_alternative (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES space_history_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), alternative_id TEXT NOT NULL, name TEXT NOT NULL);
CREATE TABLE space_history_alternative_checkpoint (id INTEGER PRIMARY KEY, alternative_row_id INTEGER NOT NULL REFERENCES space_history_alternative(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), checkpoint_id TEXT NOT NULL);
